'use strict';
const DISTRICTS_UI6={cityView,bind,openDialog,help};
function districtProjectsHtml6(projects){return projects.length?projects.map(p=>`<div class="vote"><div><strong>${esc(DISTRICT_PROJECTS6[p.type].name)}</strong><small>${esc(loc(p.location).name)} · T${p.start}–${p.finish-1} · ${p.applied?'dokončeno':state.week>=p.start?'probíhá':'ohlášeno'}<br>Provoz při pracích ${round(DISTRICT_PROJECTS6[p.type].works*100)} % · po dokončení ${DISTRICT_PROJECTS6[p.type].foot>=0?'+':''}${number(DISTRICT_PROJECTS6[p.type].foot*100,1)} bodů pěšího indexu</small></div><button class="soft mini" data-district-address6="${p.location}">Adresa</button></div>`).join(''):empty('Pro tuto adresu teď nejsou ohlášené práce.');}
function districtAddressHtml6(id){const c=districtContext6(id),reports=state.districts6.reports.filter(r=>r.location===id).slice(-3).reverse();return `<section class="card" id="districtPanel6"><span class="eyelabel">OKOLÍ VYBRANÉ ADRESY</span><h2>${esc(c.name)} · místní hosté</h2>${rows([['Pracovní místa v okolí',number(c.officeJobs)],['Školy / kulturní a turistické cíle',c.schools+' / '+c.attractions],['Rezidenti v okolí',number(c.residents)],['Pohodlí pěšího přístupu',c.walkScore+'/100'],['Pěší index / výchozí stav',c.trafficIndex+' / 100'],['Index nových nájemních nabídek',number(c.rent*100,1)+' %']])}<p class="sub">Okolí je součástí herní simulace. Počty jsou modelové odhady. Pěší index porovnává tuto adresu s jejím původním stavem; pevný nájem se přecení až při obnově smlouvy.</p><div class="district-mix6">${GUEST_KEYS5.map((k,i)=>`<span>${esc(GUEST_TYPES5[k].name)} <strong>${number(c.mix[i]*100,1)} %</strong></span>`).join('')}</div><h3>Ohlášené změny okolí</h3>${districtProjectsHtml6(c.announced)}<h3>Průzkum před investicí</h3><p class="sub">Porovná 3 koncepty a 3 cenové úrovně pro základní novou kavárnu. Základní odhad ±25 %, podrobný ±8 %. Objednávka stejného průzkumu v témže týdnu otevře zaplacený výsledek.</p><div class="actions">${Object.entries(MARKET_RESEARCH6).map(([tier,t])=>`<button class="soft" data-research-quote6="${tier}" data-research-address6="${id}">${t.name} · ${money(marketResearchQuote6(id,tier).fee)}</button>`).join('')}</div>${reports.map(r=>`<button class="quiet" data-research-report6="${r.id}">${esc(MARKET_RESEARCH6[r.tier].name)} · T${r.week} · ${state.week>r.validUntil?'starší odhad':'platný do T'+r.validUntil} →</button>`).join('')}</section>`;}
cityView=function(){const html=DISTRICTS_UI6.cityView();if(selected&&loc(selected)?.city===city)return html.replace('<section class="card listing">',districtAddressHtml6(selected)+'<section class="card listing">');const projects=state.districts6.projects.filter(p=>loc(p.location).city===city&&!p.applied);return html+`<section class="card"><h2>Plány okolí · ${esc(city)}</h2><p class="sub">Prohlédni si ohlášené práce ještě před výběrem první adresy.</p>${districtProjectsHtml6(projects)}</section>`;};
function districtResearchReport6(id){const r=state.districts6.reports.find(r=>r.id===id);if(!r)throw Error('Průzkum není v archivu.');const rec=r.recommended;show(`<span class="eyelabel">${esc(MARKET_RESEARCH6[r.tier].name)} · ZAPLACENÝ REPORT</span><h2>${esc(loc(r.location).name)}</h2><p>Odhad z T${r.week} · orientačně do T${r.validUntil} · nejistota ±${round(r.error*100)} %. ${state.week>r.validUntil?'Průzkum zestárl; aktuální okolí může být jiné.':''}</p>${rows([['Doporučený koncept',CONCEPTS[rec.concept].name],['Průměrná cena nápoje včetně DPH',money(rec.price)],['Odhad návštěv týdně',number(rec.low)+'–'+number(rec.high)],['Provozní zisk kavárny / týden',money(rec.profitLow)+' až '+money(rec.profitHigh)]])}<div class="district-table6"><table><thead><tr><th>Koncept</th><th>Nápoj s DPH</th><th>Návštěvy / týden</th><th>Zisk kavárny / týden</th></tr></thead><tbody>${r.estimates.map(e=>`<tr><td>${esc(CONCEPTS[e.concept].name)}</td><td>${money(e.price)}</td><td>${number(e.low)}–${number(e.high)}</td><td>${money(e.profitLow)} až ${money(e.profitHigh)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Model základní nové kavárny: značka ${esc(r.company.brand)}, káva ${esc(r.company.blend)}, pověst firmy ${number(r.company.reputation,1)}. Zohledňuje současné okolí, sezónu, konkurenty, obsluhu, mzdy včetně odvodů a přesčasů, nájem, suroviny, DPH a odpisy. Předpokládá průběžné dodávky kávy. Zisk nezahrnuje centrálu ani daň firmy; investice do otevření se platí zvlášť. Není to záruka ani report existující kavárny. Ohlášené projekty mohou odhad změnit ještě před jeho vypršením.</p><h3>Plány známé při průzkumu</h3>${districtProjectsHtml6(r.changes)}<button class="soft" id="researchBack6">Zpět na adresu</button>`);on('[data-district-address6]',b=>districtGo6(b.dataset.districtAddress6));el('researchBack6').onclick=()=>districtGo6(r.location);}
function districtGo6(id){el('modal').close();selected=id;city=loc(id).city;goto('city');}
function districtResearchQuote6(id,tier){const q=marketResearchQuote6(id,tier),cfg=MARKET_RESEARCH6[tier];if(q.cached)return districtResearchReport6(q.cached);show(`<h2>${esc(cfg.name)} · ${esc(loc(id).name)}</h2>${rows([['Jednorázová cena',money(q.fee)],['Hotovost po objednávce',money(q.cash-q.fee)],['Nejistota odhadu','±'+round(cfg.error*100)+' %'],['Platnost odhadu',cfg.valid+' týdnů při stejných podmínkách']])}<p class="sub">Dostaneš porovnání konceptů, cen, návštěvnosti a provozního zisku základní kavárny. Objednávka neotevírá podnik ani nemění tvoje značky. Starší zaplacený report zůstane v archivu.</p><div class="actions"><button class="primary" id="researchBuy6" ${state.over||state.cash<q.fee?'disabled':''}>Zaplatit a získat report</button><button class="soft" id="researchCancel6">Zrušit</button></div>`);el('researchCancel6').onclick=()=>el('modal').close();el('researchBuy6').onclick=()=>act(()=>{const r=runMarketResearch6(id,tier,q);persist();render();districtResearchReport6(r.id)});}
bind=function(){DISTRICTS_UI6.bind();on('[data-district-address6]',b=>districtGo6(b.dataset.districtAddress6));on('[data-research-quote6]',b=>districtResearchQuote6(b.dataset.researchAddress6,b.dataset.researchQuote6));on('[data-research-report6]',b=>districtResearchReport6(b.dataset.researchReport6));};
openDialog=function(id,...args){DISTRICTS_UI6.openDialog(id,...args);const c=districtContext6(id),p=document.createElement('p');p.className='sub';p.textContent='Okolí: pěší index '+c.trafficIndex+'/100. '+(c.announced.length?c.announced.map(p=>DISTRICT_PROJECTS6[p.type].name+' T'+p.start+'–'+(p.finish-1)).join('; '):'Aktuálně bez ohlášených prací.');el('modalContent').append(p);};
help=function(){DISTRICTS_UI6.help();const p=document.createElement('p');p.textContent='Na mapě vyber adresu: okolí ukazuje kanceláře, školy, rezidenty, turisty a pěší přístup. Ohlášené projekty nejprve omezí provoz, po dokončení mohou změnit místní hosty a nové nájemní nabídky. Placený průzkum porovná koncepty a ceny v aktuálním provozním modelu. Výsledek s rozmezím nejistoty zůstává uložený a nezmění se při čtení.';el('modalContent').append(p);};el('help').onclick=help;render();
